/** Why the microphone couldn't start. */
type MicrophoneError =
  /** The person or a policy refused access: NotAllowedError, SecurityError. */
  | "not-allowed"
  /** No microphone, or none matching the constraints: NotFoundError, OverconstrainedError. */
  | "not-found"
  /** The device exists but couldn't be opened, like another app holding it: NotReadableError, AbortError. */
  | "not-readable"
  /** `getUserMedia` needs HTTPS (or localhost); the page isn't a secure context. */
  | "insecure-context"
  /** The browser has no `getUserMedia`. */
  | "unsupported"
  | "unknown"

type MicrophoneResult =
  | { state: "listening"; stream: MediaStream }
  | { state: "denied" | "error"; error: MicrophoneError; cause?: unknown }

const defaultConstraints: MediaTrackConstraints = {
  echoCancellation: true,
  noiseSuppression: true,
  autoGainControl: true,
}

function microphoneError(cause: unknown): MicrophoneError {
  const name =
    cause instanceof Error || (typeof DOMException !== "undefined" && cause instanceof DOMException) ? cause.name : ""
  if (name === "NotAllowedError" || name === "SecurityError" || name === "PermissionDeniedError") return "not-allowed"
  if (name === "NotFoundError" || name === "OverconstrainedError" || name === "DevicesNotFoundError") return "not-found"
  if (name === "NotReadableError" || name === "AbortError" || name === "TrackStartError") return "not-readable"
  return "unknown"
}

/**
 * Optional: asks for the microphone and maps the outcome onto a voice input's states. Call it from the press that
 * starts listening (`onStart`), never on page load. `denied` means the person or a policy refused; `error` covers a
 * missing, busy or unsupported device. Stop the stream's tracks when you're done (`stopStream`), or the browser keeps
 * showing that the microphone is in use.
 */
async function requestMicrophone(audio: MediaTrackConstraints | true = defaultConstraints): Promise<MicrophoneResult> {
  if (typeof navigator === "undefined" || typeof navigator.mediaDevices?.getUserMedia !== "function") {
    const insecure = typeof isSecureContext === "boolean" && !isSecureContext
    return { state: "error", error: insecure ? "insecure-context" : "unsupported" }
  }
  try {
    return { state: "listening", stream: await navigator.mediaDevices.getUserMedia({ audio }) }
  } catch (cause) {
    const error = microphoneError(cause)
    return { state: error === "not-allowed" ? "denied" : "error", error, cause }
  }
}

/** Stops every track of a stream, which turns the browser's recording indicator off. */
function stopStream(stream: MediaStream | null | undefined) {
  for (const track of stream?.getTracks() ?? []) track.stop()
}

export { microphoneError, requestMicrophone, stopStream }
export type { MicrophoneError, MicrophoneResult }

import { announce, createChange, definePrimitive, type ChangeDetails, type ChangeSource } from "@ui-sdk/core"

import { settled, unavailable } from "@/lib/action-refusal"

/** Where a voice input is: the microphone is off, being asked for, heard, the words are being worked on, or it failed. */
type VoiceInputState = "idle" | "requesting" | "listening" | "processing" | "error" | "denied"

/**
 * Why the state should change: the Dictate toggle (`trigger-press`), the cancel button (`close-press`), Escape, or a
 * call from an agent or your code (`imperative`).
 */
type VoiceInputStateChangeReason = "trigger-press" | "close-press" | "escape-key" | "imperative"

type VoiceInputStateDetails = ChangeDetails<VoiceInputStateChangeReason>

type VoiceInputOptions = {
  state?: VoiceInputState
  defaultState?: VoiceInputState
  /**
   * Asks for the next state: `requesting` to start, `processing` to finish and keep what was said, `idle` to discard.
   * The voice input never changes it itself while `state` is passed; `details.cancel()` refuses it.
   */
  onStateChange?: (state: VoiceInputState, details: VoiceInputStateDetails) => void
  /** Read politely when the state becomes each one; a state without text says nothing. */
  announcements?: Partial<Record<VoiceInputState, string>>
  disabled?: boolean
}

const startable = new Set<VoiceInputState>(["idle", "error", "denied"])
const cancelable = new Set<VoiceInputState>(["requesting", "listening", "processing"])

const voiceInput = definePrimitive({
  name: "voice-input",
  options: {
    state: "string",
    defaultState: "string",
    onStateChange: "callback",
    announcements: "value",
    disabled: "boolean",
  },
  controlled: ["state"],
  state: (options: VoiceInputOptions) => ({
    state: options.state ?? options.defaultState ?? "idle",
    disabled: options.disabled ?? false,
  }),
  sync: (options) => ({
    ...(options.state === undefined ? {} : { state: options.state }),
    disabled: options.disabled ?? false,
  }),
  api: (context) => {
    const change = createChange(context)
    let previous = context.store.get().state
    const unsubscribe = context.store.subscribe(() => {
      const { state } = context.store.get()
      if (state === previous) return
      previous = state
      const text = context.options().announcements?.[state]
      if (text) announce(text)
    })
    context.onDestroy(unsubscribe)

    // A UI SDK Toggle reports its press without the event; its own details say who pressed it.
    let pressedBy: ChangeSource | undefined
    const request = (action: string, next: VoiceInputState, reason: VoiceInputStateChangeReason, event?: Event) =>
      settled(change("state", next, { reason, event, ...(pressedBy ? { source: pressedBy } : {}) }), action, {
        reason,
        event,
      })
    const refuse = (action: string, reason: VoiceInputStateChangeReason, event?: Event) => {
      const { state, disabled } = context.store.get()
      return unavailable(action, `isn't available while ${disabled ? "disabled" : state}`, { reason, event })
    }

    const api = {
      /** Asks to start listening: `requesting`. From idle, after an error or after a denial (to try again). */
      start(event?: Event, reason: VoiceInputStateChangeReason = "imperative") {
        const { state, disabled } = context.store.get()
        if (disabled || !startable.has(state)) return refuse("start", reason, event)
        return request("start", "requesting", reason, event)
      },
      /** Asks to stop listening and keep what was said: `processing`. */
      confirm(event?: Event, reason: VoiceInputStateChangeReason = "imperative") {
        if (context.store.get().state !== "listening") return refuse("confirm", reason, event)
        return request("confirm", "processing", reason, event)
      },
      /** Asks to stop and discard: `idle`. While asking for the microphone, listening or processing. */
      cancel(event?: Event, reason: VoiceInputStateChangeReason = "imperative") {
        if (!cancelable.has(context.store.get().state)) return refuse("cancel", reason, event)
        const root = context.element("root")
        const focused = root?.contains(root.ownerDocument.activeElement) === true
        if (!request("cancel", "idle", reason, event)) return false
        // The cancel button leaves with the state, so focus moves to the toggle, which is always there.
        if (focused) root?.querySelector<HTMLElement>("[data-voice-input-toggle]")?.focus()
        return true
      },
      /** What the Dictate toggle does: start, finish while listening, or give up waiting for the microphone. */
      toggle(event?: Event, source?: ChangeSource) {
        const { state } = context.store.get()
        pressedBy = source
        try {
          if (state === "listening") return api.confirm(event, "trigger-press")
          if (state === "requesting") return api.cancel(event, "trigger-press")
          return api.start(event, "trigger-press")
        } finally {
          pressedBy = undefined
        }
      },
    }
    return api
  },
  slots: (slot) => ({
    root: slot<{}, { state: VoiceInputState; active: boolean; disabled: boolean }>({
      role: "group",
      state: (state) => ({
        state: state.state,
        active: state.state === "requesting" || state.state === "listening" || state.state === "processing",
        disabled: state.disabled,
      }),
      attrs: (state) => ({
        "data-state": state.state,
        "aria-busy": state.state === "requesting" || state.state === "processing" ? "true" : undefined,
        "data-disabled": state.disabled ? "" : undefined,
      }),
      on: {
        keydown: (event, { api, store }) => {
          const keyboard = event as KeyboardEvent
          const { state } = store.get()
          // Only while it's on, so Escape still closes a dialog or clears a field around an idle voice input.
          if (keyboard.key !== "Escape" || (state !== "listening" && state !== "requesting")) return
          keyboard.preventDefault()
          keyboard.stopPropagation()
          api.cancel(keyboard, "escape-key")
        },
      },
    }),
  }),
  agent: { actions: ["start", "confirm", "cancel"] },
})

export { voiceInput }
export type { VoiceInputOptions, VoiceInputState, VoiceInputStateChangeReason, VoiceInputStateDetails }

"use client"

import { useEffect, useEffectEvent, useRef, useState, useSyncExternalStore } from "react"

import { createAudioMeter, type AudioLevelFrame, type AudioMeter, type AudioMeterOptions } from "@/lib/audio-meter"

type UseAudioLevelOptions = Omit<AudioMeterOptions, "target" | "steps"> & {
  /** `false` stops sampling, as while a voice input isn't listening. */
  active?: boolean
  /** How many steps the level takes under `prefers-reduced-motion: reduce`, where bars also hold still. */
  reducedMotionSteps?: number
}

const reducedMotionQuery = "(prefers-reduced-motion: reduce)"

function subscribeReducedMotion(notify: () => void) {
  if (typeof matchMedia !== "function") return () => {}
  const list = matchMedia(reducedMotionQuery)
  list.addEventListener("change", notify)
  return () => list.removeEventListener("change", notify)
}

const prefersReducedMotion = () => typeof matchMedia === "function" && matchMedia(reducedMotionQuery).matches

/**
 * The microphone level of `stream`, for a visual of your own, without a React render per frame. Put `ref` on the
 * element to style: it gets `--voice-level` (0–1) and, with `bars`, `--voice-bar-0`… as custom properties. Or draw in
 * `onFrame`, or read `level()` when you need it. Sampling stops while `active` is false, the page is hidden or the
 * stream ends, and under reduced motion the level moves in a few steps.
 */
function useAudioLevel(stream: MediaStream | null | undefined, options: UseAudioLevelOptions = {}) {
  const { active = true, reducedMotionSteps = 4, bars = 0, barInterval, floorDb, ceilingDb, attack, release } = options
  const [element, setElement] = useState<HTMLElement | null>(null)
  const reduced = useSyncExternalStore(subscribeReducedMotion, prefersReducedMotion, () => false)
  const meter = useRef<AudioMeter | null>(null)
  const onFrame = useEffectEvent((frame: AudioLevelFrame) => options.onFrame?.(frame))
  const onEnd = useEffectEvent(() => options.onEnd?.())

  useEffect(() => {
    if (!stream || !active) return
    const created = createAudioMeter(stream, {
      target: element,
      bars,
      barInterval,
      floorDb,
      ceilingDb,
      attack,
      release,
      steps: reduced ? reducedMotionSteps : 0,
      onFrame: (frame) => onFrame(frame),
      onEnd: () => onEnd(),
    })
    meter.current = created
    return () => {
      created.stop()
      meter.current = null
    }
  }, [stream, active, element, bars, barInterval, floorDb, ceilingDb, attack, release, reduced, reducedMotionSteps])

  return { ref: setElement, level: () => meter.current?.level() ?? 0 }
}

export { useAudioLevel }
export type { UseAudioLevelOptions }

"use client"

import { useMemo, useState, useSyncExternalStore } from "react"

// The seconds since `startedAt`, held still while not running, so a finished recording keeps its length.
function createClock() {
  let seconds = 0
  let from: number | undefined
  return {
    read(startedAt: number | undefined, running: boolean) {
      if (startedAt === undefined) return 0
      if (running || from !== startedAt) {
        from = startedAt
        seconds = Math.max(0, Math.floor((Date.now() - startedAt) / 1000))
      }
      return seconds
    },
  }
}

// Wakes once per whole second since `startedAt`, so a timer renders at most once a second and never drifts.
function subscribeSeconds(startedAt: number | undefined, running: boolean) {
  return (notify: () => void) => {
    if (startedAt === undefined || !running) return () => {}
    let timer: ReturnType<typeof setTimeout> | undefined
    const schedule = () => {
      timer = setTimeout(
        () => {
          notify()
          schedule()
        },
        1000 - ((Date.now() - startedAt) % 1000) + 5,
      )
    }
    schedule()
    return () => clearTimeout(timer)
  }
}

/** Whole seconds since `startedAt` (an epoch time in ms), counting while `running`. */
function useElapsedSeconds(startedAt: number | undefined, running: boolean) {
  const [clock] = useState(createClock)
  const subscribe = useMemo(() => subscribeSeconds(startedAt, running), [startedAt, running])
  return useSyncExternalStore(
    subscribe,
    () => clock.read(startedAt, running),
    () => 0,
  )
}

